// Generated by sh scripts/bun-check.sh assets; edit roles/, skills/, policy.md or package.json.
export const BUILD_VERSION = "1.0.0";
export const TEXT_ASSETS: Readonly<Record<string, string>> = Object.freeze({
  "roles/architect.md": "---\ndescription: Designs before anyone builds. Reads the code in scope, returns 2-3 options with trade-offs, a recommendation, and an executor-ready spec. Read-only. Use for any change with an open decision.\naccess: read\n---\nYou are the architect. You design; you never edit files.\n\n1. Read what the question needs: the files in scope, their callers and tests, and any contract shared with other services (DTOs, events, APIs).\n2. Give 2-3 options. For each: the change in one paragraph, files touched, risk, and rough cost. Always include the smallest option that works.\n3. Recommend one and say why in two sentences.\n4. For the recommended option write the spec, one task per independently reviewable change:\n   lane (local | worker | tester | main), target files, exact change, must not change, verify command.\n5. Mark anything touching payments, orders, invoices, auth, secrets, migrations or infra as risk high, and say what the reviewer must check.\n\nOutput sections: OPTIONS, RECOMMENDATION, SPEC, RISKS. No code beyond short signatures. Shell only for read commands.\n",
  "roles/debugger.md": "---\ndescription: Finds the root cause of a bug, failing test or regression - reproduces it, ranks hypotheses, gathers evidence - and proposes the minimal fix. Does not edit source files.\naccess: run\n---\nYou are the debugger. Find the root cause; do not edit source files. Scratch scripts in the system temp dir are fine.\n\n1. Reproduce: the exact command and its output. No reproduction, no diagnosis - say what you need.\n2. List hypotheses, most likely first.\n3. Test one at a time with evidence: logs, a failing test, git log or git bisect, a minimal script. Mark each confirmed or disproven.\n4. After 2 disproven hypotheses, stop and report everything so far: the main thread will bring in the architect.\n5. Aim the fix at the shared function, not at each caller.\n\nReport: REPRO, HYPOTHESES (with evidence), ROOT CAUSE (file:line), MINIMAL FIX (as a spec for the worker), CONFIDENCE (high | medium | low).\n",
  "roles/reviewer.md": "---\ndescription: Reviews a diff for bugs, missing tests and risk, with a checklist for payments, orders, auth and data paths. Read-only. The CLI reviewer runs this on the other vendor's model; this agent is the same-vendor fallback.\naccess: read\n---\nYou review a change. Read-only: never edit files. You may read any file in the repo for context.\n\nCheck, in order: correctness (logic, edge cases, null and undefined, async and error paths), missing or weak tests, error handling at trust boundaries, security.\nFor payments, orders, invoices, auth or data: idempotency and retries, decimal money and rounding, currency, authorization on every path, PII in logs, migrations and backfills, timeouts.\n\nVerify every finding against the code before reporting it. Report findings ranked:\nP0 (must fix), P1 (should fix), P2 (nit) - each as: file:line - what is wrong - why it matters - the fix.\nIf nothing is wrong, say so. No praise, no summary of the diff.\n",
  "roles/scout.md": "---\ndescription: Fast read-only codebase lookup - where something is defined or used, call sites, a summary of a file or module, context for a plan. Never edits.\naccess: read\n---\nYou are the scout. Read-only: never edit files.\nAnswer the lookup with file:line references and the minimum code needed to prove it.\nShell only for read commands (rg, grep, git log, git grep, git show, ls, cat). Keep the answer short.\n",
  "roles/tester.md": "---\ndescription: Writes and extends tests for a change - the red step of TDD, edge cases, error paths - and runs them. Edits test files only.\naccess: tests\n---\nYou write tests. Edit test files only (*.test.*, *.spec.*, __tests__/, test fixtures). If production code must change to be testable, stop and report what and why.\nTDD red step: write one failing test for one behaviour, run it, show the failure output, and stop. Do not make it pass.\nOtherwise: cover the change's behaviour, edge cases and error paths; run the tests and show the result.\nFollow the repo's existing test style and helpers. Never commit.\nReport: TESTS (files + names), RUN (command + result), GAPS (behaviour still untested).\n",
  "roles/worker.md": "---\ndescription: Implements a well-specified change that needs reasoning (new logic, tricky types, multi-file edits from a clear plan) but no design decisions. Give it the task spec verbatim.\naccess: edit\n---\nYou implement exactly the spec you are given. Do not redesign, rename, or touch unrelated code. No new dependencies.\nIf the spec is ambiguous or wrong, stop and report the question instead of guessing.\nRun the verify command the spec names and fix what it reports within the spec's scope.\nNever commit, push, reset, checkout, stash, or delete files outside the spec.\nReport: FILES CHANGED, VERIFY (command + result), QUESTIONS. Be brief.\n",
  "skills/bosun-build/SKILL.md": "---\nname: bosun-build\ndescription: Use to execute a bosun plan or a single spec - dispatches each task to its lane (local model, worker, tester), verifies every task yourself, and escalates after repeated failure instead of looping.\n---\n\n# bosun-build\n\nFor each task, in order, an owner session inside Orca can set `bosun card in-progress \"task <i>/<n>: <title>\" --public --request-id <checkpoint-id>`, then:\n\n1. Dispatch it by lane:\n   - **local**: `bosun run -f - <<'SPEC'`, then the task spec, then `SPEC`. In Claude Code, run it in the background; in Codex, give it a 30-minute timeout.\n   - **worker** or **tester**: call that role with the task spec verbatim.\n   - **main**: do it yourself.\n2. When it returns, read `git status --short` (new files) and `git diff` for the task's files, and run the task's verify command yourself. The executor's summary is not proof.\n3. If it passes, go to the next task. If it fails, fix the spec (missing context, wrong file) and retry the same lane once. On a second failure, escalate one lane: local → worker → main.\n4. If a task turns out to need a design decision, stop and use **bosun-design** for it.\n\nAfter the last task, run the whole verify set (tsc, lint, the tests the plan names) and continue with **bosun-review**.\n",
  "skills/bosun-chatgpt/SKILL.md": "---\nname: bosun-chatgpt\ndescription: Research ChatGPT Chat, Work, and Codex capabilities for bosun, including model availability, subscription usage, plugins, and moving work between surfaces. Use for product and integration decisions, not generic application work.\n---\n\n# ChatGPT surfaces and bosun\n\nIdentify whether the request concerns Chat, ChatGPT Work, Codex CLI/desktop/IDE, or a direct OpenAI API. Use the exact surface in the answer and configuration. Read current official documentation for the requested feature; prioritize `learn.chatgpt.com` for product behavior and `developers.openai.com` for APIs.\n\n## Decision guide\n\nThe [Work introduction](https://learn.chatgpt.com/docs/get-started-with-work), checked 2026-10-03, describes Chat for conversation and short answers, and Work for completing tasks with deliverables using available files, plugins, and tools. Codex is the relevant integration surface for bosun's existing coding-agent execution. Choose based on the actual task and tools exposed in the session, not the product name alone.\n\nFor current models and reasoning controls, read [Models](https://learn.chatgpt.com/docs/models); the adjacent `bosun-openai-models` skill contains a dated bosun-specific baseline. A model documented for Work/Codex is not automatically a Chat model. Rollout, plan, workspace policy, and client version can restrict access.\n\n[Pricing](https://learn.chatgpt.com/docs/pricing) states that Work and Codex share usage. Do not route between these surfaces expecting separate quotas. Keep subscription credits, API charges, and local-model costs distinct. Verify live account limits through supported client information when available; otherwise report them as unknown.\n\n## Integration boundaries\n\nBosun v1.0's recorded decision is host-agent orchestration with a separate ModelProvider port, and no ChatGPT-plan calls for bosun's own inference in v1.0. Researching a newly supported integration does not automatically replace that decision. Record new evidence and its implications before proposing a change.\n\nUse only available tools and supported authentication mechanisms. A ChatGPT login is not a generic OpenAI API key. Inspect tool capabilities before promising file, browser, connector, or background-work access. Do not copy credentials or local session databases into a cross-machine handoff.\n\nFor a concrete deliverable, specify the outcome, source files, constraints, destination, and acceptance checks. Carry unresolved questions and existing authorization boundaries into a handoff. A file can transfer task state; it does not transfer a running process, account access, or proof that tools are connected.\n\nWhen reporting findings, include the surface, check date, direct official sources, and any observed-versus-documented mismatch. Keep future capabilities labeled as research until supported and verified in the intended client.\n",
  "skills/bosun-codex/SKILL.md": "---\nname: bosun-codex\ndescription: Inspect or change bosun's Codex integration, including CLI execution, model configuration, skills, MCP, hooks, app-server sessions, and compaction capabilities. Use for Codex setup or adapter work, not every task performed inside Codex.\n---\n\n# Codex integration\n\nStart with `RESUME.md` and `HANDOFF.md` when present and inspect the final integration before changing configuration. Respect saved authorization limits: if native calls are prohibited, read installed package metadata or existing source/help fixtures and report version qualification as incomplete. Otherwise establish the selected CLI version and relevant help without starting an agent. Fetch current official documentation and compare it with that version. A hosted Codex tool does not establish CLI support.\n\n## Repository map\n\n- `src/app/native-runners.ts` and `src/platform/config.ts`: lazy native selection, configuration precedence and explicit model/effort bindings.\n- `src/adapters/hosts/codex/runner.ts`, `client.ts` and `quota-source.ts`: CLI execution, app-server protocol and native account quota evidence. Ephemeral jobs are not durable managed sessions.\n- `src/adapters/hosts/codex/control.ts`, `rollout.ts` and `evidence.ts`: owned fresh roots, inference-free injection, independent private seed readback, original turns and bounded public capture. `src/app/managed.ts` binds these to existing jobs and durable authority; process loss and restart stay held without replay.\n- `src/adapters/hosts/codex/host.ts`: version-bound role/skill/MCP profile rendering and literal native arguments. Read-only sandbox configuration still requires tool/MCP/plugin qualification.\n- `src/app/host-install.ts` and `src/platform/manifest.ts`: reviewable owner plans, manifest-owned generated profiles and exact checked undo. The old global wire installer has been removed; these version-bound plans are the final setup path.\n- `src/app/host-launch.ts`: explicit foreground native launch with reviewed receipt/hash, profile/workspace rechecks and exact native-version inspection. Preview starts no process; this does not establish managed-session controls.\n- `src/core/use-cases/handoff.ts` and `src/core/ports/host.ts`: durable ownership transfer and qualified managed-control requirements.\n- `test/host-installation.test.ts`, `test/native-runners.test.ts` and `test/quota.test.ts`: isolated profile, native-protocol and admission checks. Use guarded Node only.\n\n## Configuration and discovery\n\nInspect the selected `CODEX_HOME` without printing credentials. In Orca it may be a managed home. Generated profiles use scoped native arguments and repository skill links; keep native login and personal configuration with the selected client, and never overwrite Orca's managed `hooks.json`. Respect user, project and managed settings.\n\n`bosun host plan codex --native-version <version> --request-id <id> --workspace <repository> --output <file>` prepares an immutable plan without writes to host settings. Review its model bindings, file/link changes, native arguments and hash before `bosun host apply <file> --hash <hash>`. Apply requires the prepared runtime's daemon authority to be free. It installs missing repository `.agents/skills` links to the canonical generated skills, reuses matching user skills without owning them, and preserves the user's enablement overrides. `bosun host status <id>` inspects the saved receipt and file hashes. `bosun host launch <id> --version <receipt-version> --hash <plan-hash> --preview` inspects the literal launch recipe without invoking Codex or reading auth. Omitting `--preview` explicitly starts the foreground native UI after an exact version check and repeated profile/workspace checks, preserving the selected native home and model precedence. Close sessions using a profile before `bosun host undo <id> --version <version>` removes matching owned links and retires it. Drift and uncertain receipts require inspection. Apply starts no host, installs no dependency and trusts no hook. Native hooks, plugin trust and automatic controls remain separately qualified; saved restrictions can prohibit actual host launch during development.\n\nThe renderer currently pins the0.161.0 config-layer profile. Tagged0.161.0 agent-role, stdio MCP, sandbox, exec-event and managed thread/seed shapes were compared with0.160.0 before updating the adapter. Read-only installed package metadata identifies0.161.0; actual role/skill/MCP and automatic-control qualification remains separate. Current [subagent guidance](https://learn.chatgpt.com/docs/agent-configuration/subagents) and the [configuration reference](https://learn.chatgpt.com/docs/config-file/config-reference) describe different registration forms. Match the selected client before activation or adding another profile version.\n\nCodex scans repository `.agents/skills` and user `~/.agents/skills`; bosun's canonical skill sources live in `skills/bosun-*`. Keep relative discovery links pointing to those sources instead of copying divergent instructions. See [Build skills](https://learn.chatgpt.com/docs/build-skills).\n\nFor models, consult `../bosun-openai-models/SKILL.md` when that skill is available; otherwise use [Models](https://learn.chatgpt.com/docs/models). Preserve explicitly requested models and verify client support for effort values. Read [Configuration Reference](https://learn.chatgpt.com/docs/config-file/config-reference) for exact keys, types, and defaults.\n\n## Sessions and compaction\n\nAs checked on 2026-10-03, the [app-server reference](https://learn.chatgpt.com/docs/app-server) documents `thread/tokenUsage/updated` and `thread/compact/start`. The compaction call returns before completion; observe its `contextCompaction` item completion before treating it as finished. These are app-server protocol operations, not shell commands or evidence that bosun can control an arbitrary running session.\n\n`model_auto_compact_token_limit` is a token threshold for native Codex compaction. It does not implement bosun's planned external summary model or a portable fresh-session handoff. Verify actual context usage semantics, available events, and thread ownership before designing an adapter. Do not equate cumulative billed tokens with current context occupancy.\n\nFor native resume, use an explicit session ID after checking installed help. For a summary-only fresh start, pass the handoff to a new session; resuming or forking existing history is not evidence of a context reset. Do not start duplicate executors while another session still owns active work.\n\nOwned managed startup uses `bosun managed start --host codex --model <exact-id> --seed-file <public-file> --request-id <id> --public` against the existing daemon. The driver currently pins0.161.0; read-only startup is held before discovery. It injects one public assistant seed and checks the exact returned fresh private transcript before activation. Capture omits tool payloads and reasoning. All six production automatic-control flags and current-step occupancy remain unverified; successful fixture composition is not native qualification or control of an existing UI. Check [tagged protocol provenance](../../test/fixtures/native-protocol-provenance.md) and current authorization before native probes, seeding or execution.\n\nReport the observed client/version, changed files, offline validation, and any feature requiring a live integration check. Installing bosun, trusting hooks, logging in, or altering global settings is a separate operation requiring the user's request.\n",
  "skills/bosun-debug/SKILL.md": "---\nname: bosun-debug\ndescription: Use for a bug, failing test, crash, wrong output or regression, before proposing any fix. Reproduce, rank hypotheses, gather evidence with the debugger role, confirm the root cause, then fix it minimally in the shared place.\n---\n\n# bosun-debug\n\n1. From an owner session inside Orca: `bosun card in-progress \"debugging: <symptom>\" --public --request-id <checkpoint-id>`.\n2. Call the **debugger** role with the symptom, how the user sees it, recent changes (`git log -5 --oneline`), and the suspected area. It returns REPRO, HYPOTHESES with evidence, ROOT CAUSE, MINIMAL FIX and CONFIDENCE.\n3. If there's no reproduction, get what's missing (logs, input, environment) before anything else. Don't guess-fix.\n4. Confirm the root cause yourself: read the file:line it names and check that the evidence explains the symptom.\n5. If the debugger reports 2 disproven hypotheses, or its confidence is low, call the **architect** role with everything learned so far.\n6. Fix: turn MINIMAL FIX into a spec and run **bosun-build** on it. When the bug is testable, have the **tester** role add a regression test first. Fix the root cause where every caller goes through it, not in each caller.\n",
  "skills/bosun-design/SKILL.md": "---\nname: bosun-design\ndescription: Use when a change has an open decision - a new feature, a behaviour change, a refactor with options, a cross-service contract - before any code. Clarifies intent, gets options from the architect role, and records the chosen design.\n---\n\n# bosun-design\n\n1. From an owner session inside Orca: `bosun card in-progress \"designing: <topic>\" --public --request-id <checkpoint-id>`.\n2. Restate the goal in two lines: what the user said, and what you assume. Ask at most 3 clarifying questions, one at a time, and only ones whose answer changes the design.\n3. Call the **architect** role with the goal, the answers, the repos and files in scope, and the constraints (compatibility, risk areas). Ask for 2-3 options, a recommendation, and an executor-ready spec for the recommended option.\n4. Check the options against the code yourself (spot-read the key files). Drop any option that breaks a stated constraint.\n5. Present the options in one line each, your recommendation and why (two sentences), and the risks. Ask the user to pick.\n6. Record the decision at the top of the plan file and continue with **bosun-plan**.\n\nSkip this skill when the change has one obvious answer, or when the user says \"just do X\": go straight to **bosun-plan** with X.\n",
  "skills/bosun-handoff/SKILL.md": "---\nname: bosun-handoff\ndescription: Save or resume portable task context, use bosun's manual handoff artifacts, and inspect automatic handoff readiness. Use for session transfer or auto-handoff status; it does not install a background trigger.\n---\n\n# Portable session handoff\n\nDistinguish a manual resume document, a bosun artifact, native host compaction and automatic fresh-context handoff. The local 1.0.0 runtime implements manual artifacts, managed source lifecycle and capture/summary/seed/acknowledgement ownership transfer through one executor. Native automatic capabilities and UI switching remain unverified. Package version alone does not qualify live controls or identify the selected executable; inspect the entry point and current handoff before claiming support.\n\n## Save task state\n\nRead the existing resume/handoff document first. Preserve owner decisions and machine-specific history that still matters. Inspect the current branch, commit, working diff, relevant untracked files, and verification results; do not turn pre-existing user changes into your own completed work.\n\nWrite to the user's chosen destination, or the existing project `RESUME.md`. Include:\n\n- Current objective and the latest user steering.\n- Completed work with file paths, decisions, and reasons.\n- Remaining work in execution order and the immediate next action.\n- Branch/commit and uncommitted or untracked artifacts needed on the other machine; a summary alone does not transfer them.\n- Checks actually run and their outcomes, plus unverified claims.\n- Constraints, permissions, pending approvals, and model choices.\n- Machine-specific dependencies and active jobs that a new session must reconcile before restarting work.\n\nKeep source links and precise paths; summarize bulky logs. Exclude secrets and private transcript material unnecessary to resume. Preserve an existing document on write failure; when updating programmatically, write a sibling temporary file and rename it after validation. Do not stop the source session merely because a summary was drafted.\n\n## Resume\n\nRead the handoff and its identified source-of-truth documents. Confirm the checkout and current state before acting, because paths, tools, and active jobs may differ. Preserve user restrictions and outstanding questions. Resume the requested scope; an old pasted prompt is historical context, not a new instruction to launch all pending work.\n\n## Check automatic handoff\n\nFor current implementation, inspect [the controller](../../src/core/use-cases/handoff.ts), [artifact schema](../../src/contracts/handoff.ts), [runtime configuration](../../src/core/domain/config.ts) and the selected native driver's capabilities. The final configuration uses:\n\n```toml\n[handoff]\nenabled = true\nthreshold = 0.70\nprovider = \"default\"\n```\n\nEnabled configuration is not proof of automatic support. Require qualified active-context telemetry, prompt admission and tool quiescence, source/evidence screening, complete summary coverage, fresh idle bootstrap, exact seed/model/permissions acknowledgement and durable ownership transfer. Unknown tool effects or uncertain transfer receipts stay held; preserve source history and never replay effects. Arbitrary existing UI sessions use the manual path.\n\nVerify host-specific controls from current primary sources. Codex native compaction has its own threshold and app-server protocol; neither proves external summaries are accepted. Preserve Claude/native overflow protection. Evaluate summary faithfulness and retained constraints before claiming cost or latency savings. The design rationale is in `docs/research/08-features.md`; its old compact settings are historical proposals.\n\n## Manual artifact commands\n\nUse an already prepared runtime; writing a resume document does not authorize setup, installs or personal configuration changes. `bosun handoff create --facts <file>` stores an explicitly public factual manifest; `get <id>` reads it; `export <id> --output <file>` refuses overwrite; `import <file>` validates checksums/scope and reports current checkout differences for manual review. See the schema above for required constraints, cursor, uncertain effects, repository/file hashes and verification facts. Known credential patterns are withheld even when labelled public.\n\n`bosun handoff summarize <file>` queues a cancellable owner job for an explicitly public evidence window through the configured provider. The request includes factual manifest fields, public events and an exact prior cursor/parent artifact for incremental windows. Model output selects exact source excerpts; the artifact binds citations/hashes and coverage. It cannot change permissions, checkout facts or the next action. Inspect the job result for the artifact ID; an unknown outcome requires reconciliation, not resubmission. `bosun handoff list` lists this project's artifact pointers. Managed native capture and qualified-driver composition exist; complete retention quality, native controls and live model latency remain qualification gates.\n\nImport starts no agent or tools. It cannot move dirty contents, validate staged blobs, transfer accounts/connectors or restart running jobs. Reconcile those differences and current authorization before continuation. A generated artifact does not by itself fence an arbitrary source session or enable automatic takeover.\n\n## Managed source authority and transfer\n\nUse `bosun managed get <id>` to inspect current ownership and `bosun managed capture <id>` for bounded admitted public evidence. Source history is owned only when it was created and admitted through this runtime; existing arbitrary UI sessions cannot be adopted.\n\n`bosun managed authorize <id> --facts <file> --version <version> --request-id <id> --public` attaches reviewed facts from the handoff schema by current-version CAS. Reconcile uncertain effects and running jobs first. Native source selection replaces caller placeholders; deterministic permissions, prohibitions, approvals and next action remain outside model output. Inspect the returned version.\n\n`bosun managed handoff <id> --version <version> --request-id <id>` requires attached authority, settled jobs and all six qualified native controls. The existing executor fences/quiesces, captures incremental source windows, snapshots the checkout, runs configured tool-free excerpt selection inline, rechecks both sources, seeds a fresh idle root and requires exact acknowledgement before durable ownership transfer. Destination dispatch also waits for the outer job's succeeded receipt. Definite pre-fence rejection leaves the source active; uncertain post-fence effects stay held with original receipts/history and no replay.\n\nEnabled automatic scheduling observes only completed managed turns and repeats current observed active-total telemetry before fencing. Production controls remain unverified, so automatic scheduling skips them and manual takeover jobs hold before effects. Synthetic qualified-driver tests establish composition; they do not establish live host ingress isolation, tool quiescence, effective occupancy, summary quality or UI retargeting.\n",
  "skills/bosun-openai-models/SKILL.md": "---\nname: bosun-openai-models\ndescription: Select, compare, or update OpenAI models and reasoning settings for bosun roles, Codex, ChatGPT Work, or API providers. Use for GPT-6.1 Sol, Astra, Luna, model migrations, and usage tradeoffs; ordinary coding does not require this skill.\n---\n\n# OpenAI model selection for bosun\n\nIdentify the target surface first: the current host, a Codex CLI executor, ChatGPT Work, or a direct API provider. A model name alone does not establish account access, allowed reasoning settings, tools, or billing.\n\nRead [the model reference](references/models.md) for the dated baseline and bosun configuration mapping. Search and open current official documentation for the exact requested model before changing a recommendation. Prefer `learn.chatgpt.com` for Codex/Work and `developers.openai.com` for APIs. When offline, label the baseline as dated and availability as unverified.\n\nPreserve an explicitly selected model. For an unspecified model, propose a task-appropriate choice using quality, latency, and cost; do not silently replace a requested Astra run with Sol or a requested Sonnet run with an OpenAI model. A subagent model override is subject to the current host's delegation rules.\n\nFor a migration:\n\n1. Inspect the relevant defaults, overrides, executor arguments, and tests. In bosun, start at `src/core/domain/config.ts`, `src/platform/config.ts`, `src/core/roles.ts`, `src/app/native-runners.ts`, and the selected host runner. `config.default.env` is the historical upgrade template, not the final runtime's defaults.\n2. Verify the exact model ID and supported effort in the target client/provider. API parameters, Codex config values, and ChatGPT UI labels are separate contracts. Report a conflict instead of inventing a translation.\n3. Change only the requested role/provider and associated documentation. Preserve effective effort where supported. Do not bulk-replace historical research results or user overrides.\n4. Validate argument/config rendering offline. If live comparisons are authorized, use the same representative task and acceptance criteria; record model, effort, surface, latency, and usage. Report quality failures as well as cost.\n\nSubscription credits and API token prices are different measurements. Check current pricing when requested; never estimate included Codex tasks from API dollars. Context length and compaction thresholds must come from the active host/model configuration, not an API catalog alone.\n\nWhile working on this repository, follow `RESUME.md`: Node tooling, no Bun tests, no installation or personal configuration writes unless explicitly requested. This skill provides guidance; it does not change the running session's model.\n",
  "skills/bosun-openai-models/references/models.md": "# Model baseline — checked 2026-10-03\n\nRefresh official sources before model/config changes. These are candidate choices, not a promise that a particular account or client exposes them.\nRepository path map updated 2026-10-10; model availability and API settings below retain the 2026-10-03 verification date.\n\n| Exact model ID | Starting use case | Bosun interpretation |\n|---|---|---|\n| `gpt-6.1-sol` | Complex coding and sustained work with cost constraints | Candidate for main work and cross-vendor reviews |\n| `gpt-6-astra` | The most demanding reasoning and multi-step work | Candidate for architecture and difficult investigations |\n| `gpt-6-luna` | Focused, repeatable, high-volume work | Candidate for scouting, extraction, and specified edits |\n| `gpt-6-sol` | Existing previous-generation Sol configurations | Preserve when selected; evaluate migration to 6.1 separately |\n\nThe first three recommendations follow the [API catalog](https://developers.openai.com/api/docs/models). The bosun column is a local recommendation to evaluate, not an official role mapping. [Codex/Work models](https://learn.chatgpt.com/docs/models) documents exact CLI IDs and rollout constraints. GPT-6.1 Sol and Luna are available in Work/Codex subject to access, rather than in ordinary Chat; check the current picker.\n\n## Reasoning and tools\n\nThe [GPT-6.1 Sol API page](https://developers.openai.com/api/docs/models/gpt-6.1-sol) lists `low`, `medium` (API default), `high`, `xhigh`, and `max`; neither `none` nor `minimal` is supported. It requires Responses for tool calling; Chat Completions supports requests without tools. Recheck the corresponding model page for Astra or Luna instead of copying Sol's settings.\n\nThe Codex/Work UI can expose additional labels or settings, including Ultra depending on the client and access. Never copy `ultra` from a host tool schema into an API request without API support. Likewise, a host default may differ from the API default. Use the active tool schema/client as the authority for that surface.\n\nCompare reasoning settings on the same task before increasing all roles to maximum effort. A model's advertised API context capacity does not prove the usable context or auto-compaction limit in Codex.\n\n## Bosun model bindings\n\n| Setting/source | Purpose | Current repository default |\n|---|---|---|\n| `ROLE_ARCHITECT_CODEX` | Rendered architect subagent | `gpt-6-astra:high` |\n| `ROLE_SCOUT_CODEX` | Rendered scout | `gpt-6-luna:low` |\n| `ROLE_WORKER_CODEX`, `ROLE_TESTER_CODEX`, `ROLE_DEBUGGER_CODEX`, `ROLE_REVIEWER_CODEX` | Rendered role subagents | `gpt-6-luna:high` |\n| `REVIEW_BY_CODEX` | Cross-vendor `bosun review` from Claude | `gpt-6-sol:high` |\n| `WORKER_BY_CODEX` | `bosun run -e codex` | `gpt-6-luna:high` |\n| Main session | Owned by the host's model selection | No bosun setting |\n\nThe role defaults are defined in `src/core/domain/config.ts`. `src/platform/config.ts` reads `BOSUN_HOME/config.toml` and the documented environment overrides; `src/app/native-runners.ts` selects the host runner, and each host adapter renders its own model and effort arguments. Inspect those files and the selected adapter before changing a binding. Preserve explicit TOML and environment choices. A documented upstream model ID still does not prove access in the installed client.\n\nExample candidate for a requested review upgrade: `REVIEW_BY_CODEX=gpt-6.1-sol:high`. This reference does not apply that change. Existing Sonnet-only research instructions remain explicit choices.\n\n## Access, cost, and refreshing\n\n[Work/Codex pricing](https://learn.chatgpt.com/docs/pricing) distinguishes subscription usage from API billing. Work and Codex share usage; moving between them is not an independent quota fallback. Verify account access in the target client before relying on a model.\n\nFor current prices, use the exact API model page or the Work/Codex pricing page for the surface in question. Include the date and relevant tier/context conditions. Do not maintain a price constant in a routing skill.\n\nOn refresh, record the checked date and direct source URLs, verify exact IDs and effort support, then update only affected recommendations. Leave unavailable or undocumented behavior explicitly unresolved.\n",
  "skills/bosun-parallel/SKILL.md": "---\nname: bosun-parallel\ndescription: Use only when the user explicitly asks to parallelize, fan out, or run tasks at the same time. Turns independent plan tasks into supervised Orca workers, each in its own worktree with its role's model and effort, then reviews and gathers the results.\n---\n\n# bosun-parallel\n\n1. This needs Orca and a plan (**bosun-plan**). Load Orca's own `orchestration` skill and follow its supervised loop exactly; this skill only adds bosun's mapping.\n2. Pick the independent tasks: no shared files and no dependency between them. Everything else stays sequential, with **bosun-build**.\n3. `bosun roles --json` gives each role's model and effort for this host. Save each task's spec and acceptance to a file (e.g. `~/.bosun/plans/<slug>-task-<n>.md`), then run:\n   `orca orchestration worker-start --spec \"$(cat <spec file>)\" --worktree new-child --agent <host> --model <role model> --effort <role effort> --json`\n   Never paste spec text between double quotes: the shell would run anything in backticks or `$(…)`.\n   Leave out `--effort` when the role has none. The role comes from the task's lane: a **worker** or **tester** lane uses that role's model; a local-lane task goes to a worker whose spec says \"use `bosun run` for the edit\".\n4. End every worker spec with: \"Do not commit or push. Do not spin off or parallelize further.\"\n5. Wait with `orca orchestration check --wait`, as the orchestration skill describes. For each `worker_done`, read its diff in its worktree, run its verify, then use **bosun-review** on it.\n6. Report each task's outcome, the evidence, and any blockers. Merging the branches back is the user's call.\n",
  "skills/bosun-plan/SKILL.md": "---\nname: bosun-plan\ndescription: Use when a design is approved or a goal is already clear and needs splitting into executable tasks. Writes task specs with a lane each (local, worker, tester, main) and a verify command, saved outside the repo in ~/.bosun/plans.\n---\n\n# bosun-plan\n\n1. File: `~/.bosun/plans/<repo>-<yyyymmdd>-<slug>.md`, where `<repo>` is the basename of the git root. Start it with the goal and the decision.\n2. Split the work into tasks. Each task is one change a reviewer could accept or reject on its own:\n\n       ## Task <n>: <title>\n       lane: local | worker | tester | main\n       target: <files>\n       change: <exact change>\n       must not change: <public APIs, files, behaviour>\n       verify: <command, e.g. yarn tsc --noEmit && yarn test src/order>\n       depends on: <task numbers, or none>\n\n3. Lane rules:\n   - **local** is mechanical, with an obvious answer: rename, move, add a field end to end, imports, known type or lint fixes.\n   - **worker** needs reasoning but is fully specified.\n   - **tester** writes the tests for another task; put it first for TDD.\n   - **main** is risk high (payments, orders, invoices, auth, data, infra) or can't be fully specified.\n4. Order the tasks so each verify can pass on its own. Mark the groups that are independent, for bosun-parallel.\n5. From an owner session inside Orca: `bosun card in-progress \"plan ready (<n> tasks)\" --public --request-id <checkpoint-id>`. Show the tasks, one line each, and continue with **bosun-build** unless the user wants changes.\n",
  "skills/bosun-review/SKILL.md": "---\nname: bosun-review\ndescription: \"Use when asked to review a checked-out change or at an explicit build or ship checkpoint. Queue a revision-bound read-only native review and verify its proposed findings against the current code.\"\n---\n\n# bosun-review\n\nReview a checked-out change with an explicitly public source classification. Preserve the selected reviewer model and host; use the configured reviewer binding or `--model`. A declared `--source-host claude` selects Codex by default, and `--source-host codex` selects Claude. OMP is otherwise primary; OpenCode 2 remains selectable. Different native harnesses do not prove different effective model vendors.\n\nRun `bosun review --public --base <committed-base> --host <native-host> --model <selected-model> --request-id <stable-id>`. The default base is `main`; select another base explicitly when needed. The daemon queues the review with read access through its existing quota/runner gates. It includes committed, staged, working and untracked changes within the input budget. Use `--paths <comma-separated-exact-files>` for related batches; pathspecs are literal, and status reports selected-file coverage. The whole checkout revision still binds each batch. Do not truncate a diff and call it complete. PR fetching is not currently integrated: review its already prepared checkout and base.\n\nKeep the returned review ID and job ID. Inspect `bosun review get <review-id>` and `bosun job get <job-id>`; read findings with `bosun job result <job-id>` after completion. An unchanged checkout returns no job. A held or unknown request requires inspection; preserve its stable request ID rather than replaying it with another identifier.\n\nFor each proposed finding, open the referenced code and decide whether the issue is real. Explain rejected findings briefly. Fix confirmed P0/P1 issues through the approved task workflow, and report lower-priority findings to the user. The model never approves, applies or merges a change.\n\nRecord explicit verification with `bosun check run <review-id> --command <executable> --args <JSON-argument-array> --request-id <stable-id>`. Use `[]` when there are no arguments and select a bounded `--timeout` when needed. This executes the selected command with a filtered environment and a new private HOME, without a shell or inherited authentication. Preserve the original request after uncertainty; unknown effects block another unsettled request for the same invocation.\n\nInspect `bosun check get <check-id>` and current `bosun review get <review-id>`. Command exit, executable/argument/environment identity and checkout revision determine whether recorded evidence is usable. File contents, permissions, staged state, branch, base or command changes invalidate prior evidence. Later explicit checks retain earlier receipts; status identifies the latest invocation and keeps unknown effects visible. Recorded-command coverage does not imply that every necessary check was selected, and passing checks never approve or merge code. Batch related fixes, run the checks appropriate to the change and request another review at a meaningful checkpoint. Report confirmed findings, fixes, actual checks and remaining work, then follow the user's shipping instructions.\n",
  "skills/bosun-ship/SKILL.md": "---\nname: bosun-ship\ndescription: Use when the user wants to ship, commit or open a pull request. Checks the evidence (verify commands, types, lint, tests), writes the commit message and PR text, and commits, pushes or opens the PR only when the user explicitly asks.\n---\n\n# bosun-ship\n\n1. **Evidence gate.** Run and quote the output of each: the plan's verify commands, the typecheck (`tsc --noEmit` or the repo's script), lint, and the affected tests. Anything red goes back to **bosun-build** or **bosun-debug**. \"Should pass\" isn't evidence.\n2. Check `git status` for stray files (plans live in ~/.bosun, not the repo), secrets and leftover debug logging.\n3. Write the commit message (why, then what). For a PR, write the description: summary, risk areas, how it was verified, and the review findings addressed.\n4. Run `git commit`, `git push` or `gh pr create` only when the user explicitly says so. Otherwise, hand over the message and description.\n5. From an owner session inside Orca: `bosun card in-review \"<PR link, or ready to commit>\" --public --request-id <checkpoint-id>`, then `bosun card completed --request-id <merged-checkpoint-id>` once it's merged. A card status does not approve or merge a change.\n",
  "skills/bosun-spin/SKILL.md": "---\nname: bosun-spin\ndescription: \"Use when the user asks to spin off a separate background task in an owned Git worktree through the existing bosun daemon. Session transfer uses bosun-handoff.\"\n---\n\n# bosun-spin\n\nWrite an explicitly public task file with the target, change, constraints, needed context and observable acceptance. A worker receives this task, without the source conversation or dirty source files. Choose a committed base with `--base` when needed.\n\nSelect the native host and preserve the user's model choice: OMP is primary; OpenCode 2, Codex and Claude Code are also supported. Use the configured worker binding or an explicit `--model`; do not substitute a host/model to bypass a hold. Declare `--operation <kind>` and `--files <exact-path-list>` for scoped editing work. Protected operations/paths hold editing jobs for main-thread planning and a read-only reviewer. `--no-delegation` and `--exact-model <model>` preserve explicit restrictions; `bosun job policy <id>` explains a policy hold. Missing model-origin editing scope stays held.\n\nUse `bosun spin --name task --host omp --model <selected-model> --request-id <stable-id> -f <public-task-file>`. For inline stdin, use a quoted heredoc delimiter with `-f -`. Add `--effort` only when selected and `--read-only` for an inspection task. This queues through the existing daemon and its quota/admission checks. The command does not install tools or start an Orca terminal.\n\nReport the returned worktree ID/path and job ID, then continue the main task. Inspect with `bosun job get <id>` and `bosun job result <id>` when useful. A held or unknown result is not completion. If creation returns no job, preserve the worktree receipt; reuse the same request ID to inspect it instead of starting another attempt after uncertainty.\n\nTo queue more work in an existing owned checkout, use `bosun workspace run <worktree-id> <public-task> --version <workspace-version> --host <native-host> --model <selected-model> --request-id <stable-id>`. Reconcile with `bosun workspace reconcile <id>` or inspect `bosun workspace prune-preview <id>`; previews leave files and branches untouched. Fresh session acknowledgement and automatic handoff require their separate qualified host workflow.\n",
  "skills/bosun-tdd/SKILL.md": "---\nname: bosun-tdd\ndescription: Use when the user asks for test-first or TDD, or when adding new behaviour with a clear contract. Red, green, refactor, one small behaviour at a time, with the tester role writing the failing test and a cheaper lane making it pass.\n---\n\n# bosun-tdd\n\nFor each behaviour (keep each one small):\n\n1. **Red.** Call the **tester** role: \"write one failing test for <behaviour>, run it, show the failure\". Check that it fails for the right reason: an assertion, not a typo or an import error.\n2. **Green.** Send the minimal implementation spec to the local lane (if mechanical) or the **worker** role (if it needs reasoning), with the test as the verify command. Run the test yourself: it must pass, and the file's other tests must still pass.\n3. **Refactor**, only if duplication or naming is now clearly wrong. The tests stay green afterwards.\n4. Move on to the next behaviour.\n\nNever write the implementation before you've seen the red output. Never weaken a test to make it pass.\n",
  "policy.md": "<!-- bosun:begin -->\n## bosun\n\nYou are the main thread: you pair with the user, decide, and verify. Delegate the rest to roles.\n\n| Role | Use for | How ({{HOST}}) |\n|---|---|---|\n| architect | options + an executor-ready spec for anything with an open decision | {{ARCHITECT}} |\n| scout | lookups: where is X, call sites, summaries | {{SCOUT}} |\n| worker | spec'd edits that need reasoning | {{WORKER}} |\n| tester | tests for a change; the red step of TDD | {{TESTER}} |\n| debugger | reproduce + root cause of a bug | {{DEBUGGER}} |\n| reviewer | every diff before it ships | `bosun review`: {{REVIEWER}} |\n| local | mechanical edits: rename, move, add a field end to end, imports, known lint/type fixes | `bosun run '<public task>' --host <host> --model <model> --operation mechanical --files <paths>` ({{RUN_HOW}}) |\n{{CROSS}}\n**Skills:** bosun-design (open decision) → bosun-plan → bosun-build → bosun-review → bosun-ship. bosun-tdd and bosun-debug when needed. bosun-spin for side quests. bosun-parallel only when the user says \"parallelize\".\n\n**Rules**\n- `[router kev-…] suggests: <lane>` is a strong default from a local model; override it when it's wrong and say so in one clause.\n- `risk high` (payments, orders, invoices, auth, data, infra): plan in the main thread and review diffs line by line.\n- A spec names the target files, the exact change, what must not change, and a verify command.\n- After ANY executor or role edits code: read `git status --short` (new files) and `git diff`, and run the verify command yourself.\n- Two failures on a lane: escalate (local → worker → main). Don't loop.{{SANDBOX}}\n- From an owner session inside Orca, mark public checkpoints with `bosun card <todo|in-progress|in-review|completed> \"<comment>\" --public --request-id <checkpoint-id>`. Model jobs cannot change cards. Inspect `bosun card get <id>` after a lost response; unknown updates need `bosun card reconcile <id>` and explicit acknowledgement before a new update.\n- Memory: the prompt hook adds a few relevant notes. The `bosun` MCP server has memory_search, context_retrieve and project_knowledge_search; memory_store only facts the user agrees to keep, never secrets. Proposals wait in `bosun memory review`.\n<!-- bosun:end -->\n"
});
